SELECT source_id,source_user_id,authenticated_user_id
FROM t_channel_station_feedback
WHERE source_id=#{sourceId}
ORDER BY source_id
LIMIT #{limit}

SELECT source_id,source_user_id,authenticated_user_id
FROM (
  SELECT s.source_id,s.source_user_id,s.authenticated_user_id,
         ROW_NUMBER() OVER(PARTITION BY source_id ORDER BY source_id) AS source_row_number
  FROM t_channel_station_feedback s
  WHERE source_id IN
  #{sourceId}
) bounded
WHERE source_row_number<=#{perSourceLimit}
ORDER BY source_id
